SELECT /* getPopupContentCnt */
       COUNT(1)
  FROM CT_POPUPX
 WHERE POPU_SITU = #{popuSitu}
   AND POPU_CODE = #{popuCode}


SELECT /* getPopupSituCnt */
       COUNT(1)
  FROM TB_CODEXD
 WHERE COMM_CODE = #{popupSituCode}
   AND COMD_CODE = #{popuSitu}
   AND NVL(USEE_YSNO, #{yes}) = #{yes}

mapper.insert:
/* setPopupContent */
INSERT INTO CT_POPUPX (
            POPU_SITU
          , POPU_CODE
          , MNGM_TITL
          , CONT_FIRS
          , CONT_SECO
          , CONT_THIR
          , CONT_FOUR
          , REGI_ADMN
          , REGI_DATE
          , UPDT_ADMN
          , UPDT_DATE
) VALUES (  #{popuSitu}
          , #{popuCode}
          , #{mngmTitl}
          , #{contFirs}
          , #{contSeco,jdbcType=VARCHAR}
          , #{contThir,jdbcType=VARCHAR}
          , #{contFour,jdbcType=VARCHAR}
          , #{regiAdmn}
          , SYSDATE
          , #{updtAdmn}
          , SYSDATE
)

mapper.update:
UPDATE /* uptPopupContent */
       CT_POPUPX
   SET MNGM_TITL = #{mngmTitl}
     , CONT_FIRS = #{contFirs}
     , CONT_SECO = #{contSeco,jdbcType=VARCHAR}
     , CONT_THIR = #{contThir,jdbcType=VARCHAR}
     , CONT_FOUR = #{contFour,jdbcType=VARCHAR}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSDATE
 WHERE POPU_SITU = #{popuSitu}
   AND POPU_CODE = #{popuCode}
